c2={'id':'O02','order':2,'available':False,'title':'제2장. 운영체제 구조','source':{'pdf':[1],'printed':[]},'overview':['제공 파일의 목차에는 제2장이 있지만 해당 본문은 제공되지 않았다. 본문 지식은 원문에서 확인되지 않음.'],'flow':[],'sections':[], 'codes':[], 'figures':[], 'key_points':['제2장 본문은 원문에서 확인되지 않음.'], 'comparisons':[], 'review':[], 'checklist':[], 'index_terms':[], 'limitations':['목차는 인쇄 61~112쪽의 장·절을 안내하지만 실제 파일은 인쇄 59쪽 다음에 117쪽으로 넘어간다. 본문 내용을 목차 제목에서 추정하지 않았다.'],'verification':{'read_pdf_pages':[1,63,64],'visually_checked_pdf_pages':[1],'notes':['목차와 본문 불연속을 대조함.']}}
for n,t in [('2.1','운영체제 서비스'),('2.2','사용자와 운영체제 인터페이스'),('2.3','시스템 콜'),('2.4','시스템 서비스'),('2.5','링커와 로더'),('2.6','응용 프로그램이 운영체제마다 다른 이유'),('2.7','운영체제 설계 및 구현'),('2.8','운영체제 구조'),('2.9','운영체제 빌딩과 부팅'),('2.10','운영체제 디버깅'),('2.11','요약')]:
    c2['sections'].append({'number':n,'title':t+' (목차만 확인)','source':{'pdf':[1],'printed':[]},'blocks':[P('이 절의 제목만 목차에서 확인된다. 본문 내용은 원문에서 확인되지 않음.')]})
