def relfig(cid,title,p,box,meaning,offset):
    im=Image.open(ROOT/'images'/f'{p:04d}.jpg'); w,h=im.size
    return figure(cid,title,p,[round(box[0]*w),round(box[1]*h),round(box[2]*w),round(box[3]*h)],meaning,offset)
