def c4code(cid,title,p,text,meaning,process,excerpt=False,note=''):
    x=code(cid,title,p,text,meaning,process,excerpt=excerpt,note=note); x['source']=src(p,offset=-54); return x
c4['codes']=[
c4code('O04-E01','그림 4.11 Pthreads 합산 프로그램',133,r'''#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>

int sum; /* this data is shared by the thread(s) */
void *runner(void *param); /* threads call this function */

int main(int argc, char *argv[])
{
    pthread_t tid; /* the thread identifier */
    pthread_attr_t attr; /* set of thread attributes */

    /* set the default attributes of the thread */
    pthread_attr_init(&attr);
    /* create the thread */
    pthread_create(&tid, &attr, runner, argv[1]);
    /* wait for the thread to exit */
    pthread_join(tid,NULL);

    printf("sum = %d\n",sum);
}

/* The thread will execute in this function */
void *runner(void *param)
{
    int i, upper = atoi(param);
    sum = 0;

    for (i = 1; i <= upper; i++)
        sum += i;

    pthread_exit(0);
}''','main은 runner를 별도 스레드로 만들고 종료를 기다린 뒤 공유 sum을 출력한다.',['명령행 상한값을 runner의 인수로 전달한다.','runner가 1부터 upper까지 더하고 종료한다.','부모는 pthread_join() 뒤 sum에 접근한다.']),
c4code('O04-E02','OpenMP 병렬 for',148,'''#pragma omp parallel for
for (i = 0; i < N; i++) {
    c[i] = a[i] + b[i];
}''','배열 a와 b의 원소 합을 c에 넣는 반복을 생성된 스레드들에 분배한다.',['디렉티브가 병렬화할 반복문을 지정한다.','각 반복은 같은 인덱스의 a와 b를 더해 c에 저장한다.'],True,'원문 병렬 반복문 전체 발췌이며 앞의 별도 parallel 영역 예제는 포함하지 않았다.'),
c4code('O04-E03','TBB parallel_for',151,'''parallel_for (size_t(0), n, [=](size_t i) {apply(v[i]);});''','반복 공간 0부터 n−1까지의 각 i에 대해 apply(v[i])를 실행한다.',['처음 두 인수가 반복 공간을 정한다.','람다가 각 원소에 적용할 연산을 나타낸다.','라이브러리가 청크와 작업·스레드 배정을 관리한다.'],True,'원문 템플릿 호출 예제 전체 발췌이며 앞의 직렬 루프는 제외하였다.')]
